float rod (vec2 uvi) {vec3 rad1 ; float res;
uvi = fract(uvi)-.5;
rad1 = clamp01(2-64*abs(uvi.x)+exp(-uvi.y*uvi.y * 128.0));
rad1 -= .2*(uvi.x*uvi.x+uvi.y*uvi.y <= .0004);
rad1 -= .5*clamp01(1.4-uvi.x*uvi.x * 2048.0);
